<?php require_once __DIR__.'/../../app/bootstrap.php'; require_once __DIR__.'/../../app/Modules/QRExperience/helpers.php'; qrx_require_admin(); $pdo=db(); $rows=[]; try{$rows=$pdo->query("SELECT event_name,COUNT(*) total FROM qr_analytics_events WHERE created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY event_name ORDER BY total DESC")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){} ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Analitik</title><link rel="stylesheet" href="assets/studio.css"></head><body class="page"><header class="simple"><a href="index.php">← Dashboard</a><h1>Analitik</h1><p>Son 30 günlük QR menü davranış olayları.</p></header><main class="narrow"><section class="panel"><table><thead><tr><th>Olay</th><th>Toplam</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['event_name'])?></td><td><?=number_format((int)$r['total'],0,',','.')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="2">Henüz veri yok.</td></tr><?php endif;?></tbody></table></section></main></body></html>
